  localStorage.setItem(STORAGE_KEYS.tasks, JSON.stringify(tasks));
  localStorage.setItem(STORAGE_KEYS.collaboradores, JSON.stringify(collaborators));
  localStorage.setItem(STORAGE_KEYS.backup, JSON.stringify({clients, processes, documents, agenda, appointments, finances, tasks, collaborators}));
