function nextId() {
  return clients.length ? Math.max(...clients.map(c=>c.id)) + 1 : 2;
}

// --- Client CRUD ---
function addClient(name, email, phone, address) {
  const client = { id: nextId(), name, email, phone, address };
  clients.push(client);
  saveAll();
}
function updateClient(id, field, value) {
  const idx = clients.findIndex(c => c.id === id);
  if(idx !== -1) clients[idx][field] = value;
  saveAll();
}
function deleteClient(id) {
  clients = clients.filter(c => c.id !== id);
  saveAll();
}

