// --- Tab switching ---
function switchTab(tab) {
  document.querySelectorAll('.btn').forEach(b => b.classList.remove('active'));
  const btn = document.querySelector(`button.btn[onclick="switchTab('${tab}')"]`);
  if(btn) btn.classList.add('active');
}

// --- Notification alerts ---
function showAlert(type, msg) {
  const el = document.createElement('div');
  el.className = `alert ${type}`;
  el.textContent = msg;
  document.getElementById('notifications').innerHTML += `<div class="alert ${type}"><strong>${msg}</strong></div>`;
  document.getElementById('notifications').classList.remove('hidden');
  setTimeout(() => { document.getElementById('notifications').classList.add('hidden'); }, 4000);
}

