}

function renderClients() {
  const tbl = document.createElement('table');
  tbl.className = 'w-full border-collapse mb-4';
  tbl.innerHTML = `<thead><tr><th>#</th><th>Nome</th><th>Email</th><th>Telefone</th><th>Endereço</th></tr></thead><tbody>`;
  clients.forEach(c => {
    tbl.innerHTML += `<tr><td>${c.id}</td><td>${c.name}</td><td>${c.email}</td><td>${c.phone}</td><td>${c.address}</td></tr>`;
  });
  tbl.innerHTML += `</tbody></table>`;
  document.getElementById('notifications').classList.add('hidden');
  document.body.insertAdjacentElement('afterbegin', tbl);
}

