function renderAgenda() {
  const days = ['2025-09','2025-10','2025-11'];
  const today = new Date().getFullYear()+'-'+String(new Date().getMonth()+1).padStart(2,'0')+' '-'+String(new Date().getDay()).padStart(2,'0');
  const rows = [];
  for(let i=0;i<days.length;i++) {
    const dateStr = `${days[i]} ${today.split('-')[0].slice(-2)}`;
    rows.push(`<tr><td>${dateStr}</td><td></td></tr>`);
  }
  agenda.forEach(a => {
    const row = document.createElement('tr');
    row.innerHTML = `<td>${a.date}</td><td>${a.title}</td>`;
    rows.push(row);
  });
  document.body.insertBefore(rows, document.body.firstChild);
}

